"""One actual roof array and its complete server-derived official request."""

from typing import Annotated, Literal, Self

from pydantic import Field, model_validator

from .energy_inputs import Document
from .geometry_documents import Identifier
from .pvgis_request import PvgisRequest


class PvgisReferenceArray(Document):
    id: Identifier
    module_spec_id: Identifier
    # Panel identities are generated by panel_poses as array:row:column.
    module_ids: Annotated[
        list[
            Annotated[
                str, Field(pattern=r"^[A-Za-z][A-Za-z0-9_-]{0,63}:[0-9]+:[0-9]+$")
            ]
        ],
        Field(min_length=1),
    ]
    module_count: Annotated[int, Field(strict=True, gt=0)]
    stc_power_w: Annotated[float, Field(gt=0, allow_inf_nan=False)]
    normal_enu: Annotated[
        list[Annotated[float, Field(allow_inf_nan=False)]],
        Field(min_length=3, max_length=3),
    ]
    tilt_deg: Annotated[float, Field(ge=0, le=90, allow_inf_nan=False)]
    azimuth_north_clockwise_deg: Annotated[
        float, Field(ge=0, lt=360, allow_inf_nan=False)
    ]
    azimuth_basis: Literal["project_enu_normal", "horizontal_orientation_invariant"]
    request: PvgisRequest

    @model_validator(mode="after")
    def same_geometry(self) -> Self:
        if (
            self.module_count != len(self.module_ids)
            or len(set(self.module_ids)) != len(self.module_ids)
            or self.request.peak_power_kwp != self.stc_power_w / 1000
            or self.request.tilt_deg != self.tilt_deg
            or self.request.azimuth_north_clockwise_deg
            != self.azimuth_north_clockwise_deg
        ):
            raise ValueError(
                "official request must retain the exact included roof array"
            )
        return self
